302	func canViewerAccessMemo(viewer *store.User, memo *store.Memo) bool {
303		if memo == nil {
304			return false
305		}
306		if viewer != nil && isSuperUser(viewer) {
307			return true
308		}
309		if memo.Visibility == store.Private {
310			return viewer != nil && viewer.ID == memo.CreatorID
311		}
312		if memo.Visibility == store.Protected {
313			return viewer != nil
314		}
315		return true
316	}
