17				type
18			)
19			VALUES (?, ?, ?)
20			ON CONFLICT(memo_id, related_memo_id, type) DO UPDATE SET type = excluded.type
21			RETURNING memo_id, related_memo_id, type
22		`
23		memoRelation := &store.MemoRelation{}
