41	func (d *DB) ListMemoRelations(ctx context.Context, find *store.FindMemoRelation) ([]*store.MemoRelation, error) {
42		where, args := []string{"TRUE"}, []any{}
43		if find.MemoID != nil {
44			where, args = append(where, "memo_id = ?"), append(args, *find.MemoID)
45		}
46		if find.RelatedMemoID != nil {
47			where, args = append(where, "related_memo_id = ?"), append(args, *find.RelatedMemoID)
48		}
49		if find.Type != nil {
50			where, args = append(where, "type = ?"), append(args, *find.Type)
51		}
52		if len(find.MemoIDList) > 0 {
53			placeholders := make([]string, len(find.MemoIDList))
54			for i, id := range find.MemoIDList {
55				placeholders[i] = "?"
56				args = append(args, id)
57			}
58			inClause := strings.Join(placeholders, ", ")
59			for _, id := range find.MemoIDList {
60				args = append(args, id)
61			}
62			where = append(where, fmt.Sprintf("(memo_id IN (%s) OR related_memo_id IN (%s))", inClause, inClause))
63		}
64		if len(find.SourceMemoIDList) > 0 {
65			placeholders := make([]string, len(find.SourceMemoIDList))
66			for i, id := range find.SourceMemoIDList {
67				placeholders[i] = "?"
68				args = append(args, id)
69			}
70			where = append(where, fmt.Sprintf("memo_id IN (%s)", strings.Join(placeholders, ", ")))
71		}
72		if len(find.RelatedMemoIDList) > 0 {
73			placeholders := make([]string, len(find.RelatedMemoIDList))
74			for i, id := range find.RelatedMemoIDList {
75				placeholders[i] = "?"
76				args = append(args, id)
77			}
78			where = append(where, fmt.Sprintf("related_memo_id IN (%s)", strings.Join(placeholders, ", ")))
79		}
80		if find.MemoFilter != nil {
81			engine, err := filter.DefaultEngine()
82			if err != nil {
83				return nil, err
84			}
85			stmt, err := engine.CompileToStatement(ctx, *find.MemoFilter, filter.RenderOptions{Dialect: filter.DialectSQLite})
86			if err != nil {
87				return nil, err
88			}
89			if stmt.SQL != "" {
90				where = append(where, fmt.Sprintf("memo_id IN (SELECT id FROM memo WHERE %s)", stmt.SQL))
91				where = append(where, fmt.Sprintf("related_memo_id IN (SELECT id FROM memo WHERE %s)", stmt.SQL))
92				args = append(args, append(stmt.Args, stmt.Args...)...)
93			}
94		}
95	
96		query := `
97			SELECT
98				memo_id,
99				related_memo_id,
100				type
101			FROM memo_relation
102			WHERE ` + strings.Join(where, " AND ") + `
103			ORDER BY memo_id DESC`
104		if find.Limit != nil {
105			query = fmt.Sprintf("%s LIMIT %d", query, *find.Limit)
106			if find.Offset != nil {
107				query = fmt.Sprintf("%s OFFSET %d", query, *find.Offset)
108			}
109		}
110	
111		rows, err := d.db.QueryContext(ctx, query, args...)
112		if err != nil {
113			return nil, err
114		}
115		defer rows.Close()
116	
117		list := []*store.MemoRelation{}
118		for rows.Next() {
119			memoRelation := &store.MemoRelation{}
120			if err := rows.Scan(
121				&memoRelation.MemoID,
122				&memoRelation.RelatedMemoID,
123				&memoRelation.Type,
124			); err != nil {
125				return nil, err
126			}
127			list = append(list, memoRelation)
128		}
129	
130		if err := rows.Err(); err != nil {
131			return nil, err
132		}
133	
134		return list, nil
135	}
